const item = $input.first().json;
const report = item.output ?? item;
const score = report?.match_analysis?.match_score;
return [{ json: {
  ...report,
  workflow_name: 'Autonomous Job Hunter & Resume Matcher',
  generated_at: new Date().toISOString(),
  score_band: typeof score === 'number' ? (score >= 85 ? 'Excellent' : score >= 75 ? 'Strong' : score >= 55 ? 'Moderate' : 'Low') : 'Unknown'
} }];
